const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const DB={name:'tavlin',version:1,db:null,async open(){this.db=await new Promise((ok,no)=>{const q=indexedDB.open(this.name,this.version);q.onupgradeneeded=()=>{const d=q.result;if(!d.objectStoreNames.contains('recipes')){const s=d.createObjectStore('recipes',{keyPath:'id'});s.createIndex('updatedAt','updatedAt')}if(!d.objectStoreNames.contains('state'))d.createObjectStore('state',{keyPath:'key'})};q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)});return this},store(n,m='readonly'){return this.db.transaction(n,m).objectStore(n)},req(q){return new Promise((ok,no)=>{q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})},all(){return this.req(this.store('recipes').getAll())},put(v){return this.req(this.store('recipes','readwrite').put(v))},del(id){return this.req(this.store('recipes','readwrite').delete(id))},state(key){return this.req(this.store('state').get(key))},setState(key,value){return this.req(this.store('state','readwrite').put({key,value}))}};
let recipes=[],filter='',category='הכל',sortMode='newest',installPrompt=null,cook=null,tick=null,shoppingSelection=new Set(),favoriteIds=new Set(),libraryFavoritesOnly=false;
let libShown=50,libFull=[],libObs=null;const LIB_PAGE=50;
const uid=()=>crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(16).slice(2), lines=s=>s.split(/\n+/).map(x=>x.trim()).filter(Boolean), esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2400)}
async function refresh(){recipes=(await DB.all()).filter(x=>!x.deletedAt).sort((a,b)=>b.updatedAt-a.updatedAt)}
function layoutHome(){return `<section class="hero"><span class="eyebrow">ספר המתכונים המשפחתי שלך</span><h1>מה מבשלים היום?</h1><p>כל המתכונים, הזיכרונות והטעמים במקום אחד. נשמרים בחשבון תבלין ומסתנכרנים בין מכשירים. מתכונים שכבר נטענו זמינים גם בלי אינטרנט.</p><div class="search"><input id="homeSearch" placeholder="חיפוש לפי שם או מרכיב"><button class="primary" id="homeSearchBtn">חיפוש</button></div><div class="statusbar"><div class="stat"><b>${recipes.length}</b>מתכונים</div><div class="stat recipeBookStat"><b>ספר המתכונים</b><a class="bookDirect" href="#library">מעבר לספר</a></div></div></section><section class="quick"><button data-action="new"><span>✍️</span>מתכון ידני</button><button data-action="paste"><span>📋</span>הדבקת מתכון</button><button data-action="scan"><span>📷</span>סריקת דף</button><button data-view="library"><span>📖</span>ספר המתכונים</button><button data-action="suggest"><span>🤖</span>מה לבשל היום</button><button data-action="fridgeScan"><span>🧊</span>צילום מקרר</button><button data-action="aiCreate"><span>✨</span>מתכון AI</button></section><section class="libraryCta"><span>📖</span><div><h2>ספר המתכונים</h2><p>כל המתכונים נמצאים בדף ייעודי ונקי.</p></div><button class="primary" data-view="library">מעבר לכל המתכונים</button></section>`}

function card(r){const ph=r.photo?`<img loading="lazy" decoding="async" src="${r.photo}" alt="">`:'🍲';return `<article class="card"><button class="cardView" data-view-recipe="${r.id}" aria-label="\u05E6\u05E4\u05D9\u05D9\u05D4 \u05D1\u05DE\u05EA\u05DB\u05D5\u05DF ${esc(r.name)}"><div class="photo">${ph}</div><div class="cardBody"><h3>${esc(r.name)}</h3>${window.AiRecipe?AiRecipe.badgeHTML(r):''}${(typeof cook!=="undefined"&&cook&&cook.recipeId===r.id)?`<span class="cookCardBadge">🍳 ממשיך · שלב ${(cook.step||0)+1}</span>`:""}<div class="meta">${esc(r.category)} \u00B7 ${r.minutes||0} \u05D3\u05E7\u05D5\u05EA \u00B7 ${r.ingredients.length===1?'\u05DE\u05E8\u05DB\u05D9\u05D1 \u05D0\u05D7\u05D3':r.ingredients.length+' \u05DE\u05E8\u05DB\u05D9\u05D1\u05D9\u05DD'}</div><span class="primary">\u05DC\u05E6\u05E4\u05D9\u05D9\u05D4</span></div></button><button class="favToggle" data-favorite="${r.id}" aria-label="${favoriteIds.has(r.id)?'\u05D4\u05E1\u05E8\u05D4 \u05DE\u05D4\u05DE\u05D5\u05E2\u05D3\u05E4\u05D9\u05DD':'\u05D4\u05D5\u05E1\u05E4\u05D4 \u05DC\u05DE\u05D5\u05E2\u05D3\u05E4\u05D9\u05DD'}" aria-pressed="${favoriteIds.has(r.id)}">${favoriteIds.has(r.id)?'\u2665':'\u2661'}</button></article>`}
function searchNorm(x){return String(x||'').normalize('NFKC').toLocaleLowerCase('he').replace(/[\u0591-\u05c7]/g,'').replace(/[ךםןףץ]/g,c=>({'ך':'כ','ם':'מ','ן':'נ','ף':'פ','ץ':'צ'}[c])).replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
function searchNear(a,b){if(!a||!b)return false;if((a.includes(b)||b.includes(a))&&Math.min(a.length,b.length)>=3)return true;if(a.length>=4&&b.length>=4&&a[0]===b[0]&&a.replace(/[וי]/g,'')===b.replace(/[וי]/g,''))return true;if(a[0]!==b[0]||Math.abs(a.length-b.length)>1||Math.max(a.length,b.length)<4)return false;let i=0,j=0,edits=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue}if(++edits>1)return false;if(a.length>b.length)i++;else if(b.length>a.length)j++;else{i++;j++}}return edits+Math.max(a.length-i,b.length-j)<=1}
function recipeMatches(r,query){const terms=normQ(searchNorm(query)).split(' ').filter(Boolean),words=normQ(searchNorm([r.name,r.category,r.notes,...r.ingredients,...r.steps].join(' '))).split(' ').filter(Boolean);return terms.every(t=>words.some(w=>searchNear(w,t)))}
const SYN=[['עגבניות','עגבניה'],['בצלים','בצל'],['גזרים','גזר'],['תפוחי אדמה','תפוח אדמה'],['ביצים','ביצה'],['מלפפונים','מלפפון'],['פלפלים','פלפל'],['קישואים','קישוא'],['חצילים','חציל'],['פטריות','פטריה'],['שומים','שום'],['תפוזים','תפוז']];
const normQ=s=>{let t=String(s||'').toLowerCase().trim();SYN.forEach(([pl,sn])=>{t=t.split(pl).join(sn)});return t};
const CATS=['הכל','ארוחות עיקריות','דגים','מרקים','סלטים ותוספות','מאפים ופשטידות','עוגות וקינוחים','ארוחות בוקר','ילדים','שבת וחגים','אחר'];const CAT_ALIAS={'קינוח':'עוגות וקינוחים','ארוחות ערב':'ארוחות עיקריות','קלילים ובריאים':'ארוחות עיקריות'};function catOf(c){c=CAT_ALIAS[c]||c;return CATS.includes(c)&&c!=='הכל'?c:'אחר'}
function cookChipHTML(){if(!cook)return "";return `<button class="cookChip" data-action="resume" aria-label="המשך בישול">🍳 המשך בישול · ${esc(cook.recipeName)} · שלב ${(cook.step||0)+1}</button>`}
function layoutLibrary(){let shown=recipes.filter(r=>(category==='הכל'||catOf(r.category)===category)&&(!libraryFavoritesOnly||favoriteIds.has(r.id))&&(!filter||recipeMatches(r,filter)));shown.sort((a,b)=>sortMode==='alpha'?a.name.localeCompare(b.name,'he'):sortMode==='used'?(b.use_count||0)-(a.use_count||0):(b.updated_at||b.updatedAt||0)-(a.updated_at||a.updatedAt||0));libFull=shown;const page=shown.slice(0,libShown);return `<div class="sectionHead"><div><button data-view="home">← חזרה לבית</button><span class="eyebrow" style="color:var(--spice)">הספר המשפחתי</span><h1>המתכונים שלי</h1></div><button class="primary" data-action="addMenu">＋ מתכון חדש</button></div>${cookChipHTML()}<div class="search"><input id="libSearch" value="${esc(filter)}" placeholder="חיפוש בשם, מרכיב או שלב"><button id="libSearchBtn">חיפוש</button><button id="libSmartBtn" title="חיפוש חכם">✨ חכם</button></div><div class="chips catRow">${CATS.map(x=>`<button class="chip ${category===x?'active':''}" data-category="${x}">${x}</button>`).join('')}</div><div class="libraryTools"><div class="row"><button id="favoritesFilter" aria-pressed="${libraryFavoritesOnly}">${libraryFavoritesOnly?'♥ המועדפים שלי · הצגת הכל':'♡ המועדפים שלי'}</button>${modEnabled('shopping')?'<button id="selectShoppingRecipes">בחירת מתכונים לקניות</button><button id="addSelectedShopping" hidden>הוספת הנבחרים לקניות</button>':''}</div><label>מיון<select id="sortRecipes"><option value="newest" ${sortMode==='newest'?'selected':''}>החדשים ביותר</option><option value="alpha" ${sortMode==='alpha'?'selected':''}>א-ת</option><option value="used" ${sortMode==='used'?'selected':''}>לפי שימוש</option></select></label></div><p class="muted">${shown.length} תוצאות</p><div id="smartBox"></div><div class="grid" id="libGrid">${shown.length?page.map(libCardHTML).join(''):`<div class="empty"><div class="big">🔎</div><h2>לא נמצאו מתכונים</h2><p>אפשר לשנות את החיפוש או להוסיף מתכון חדש.</p></div>`}</div>${shown.length>libShown?`<div class="libMoreWrap"><div id="libSentinel" aria-hidden="true"></div><button id="libMoreBtn" class="ghost">הצג עוד ${Math.min(LIB_PAGE,shown.length-libShown)} מתכונים (${shown.length-libShown} נותרו)</button></div>`:''}`}

function libCardHTML(r){return shoppingSelection.size?`<div><label class="selectRecipe"><input type="checkbox" data-select-shopping="${r.id}" ${shoppingSelection.has(r.id)?'checked':''}> ${esc(r.name)}</label>${card(r)}</div>`:card(r)}
function libAppendMore(){const grid=$('#libGrid');if(!grid||!libFull.length)return;libShown+=LIB_PAGE;const page=libFull.slice(libShown-LIB_PAGE,libShown);grid.insertAdjacentHTML('beforeend',page.map(libCardHTML).join(''));bindCards(grid);const wrap=$('.libMoreWrap');if(libShown>=libFull.length){if(wrap)wrap.remove()}else{const b=$('#libMoreBtn');if(b)b.textContent=`הצג עוד ${Math.min(LIB_PAGE,libFull.length-libShown)} מתכונים (${libFull.length-libShown} נותרו)`;observeLibSentinel()}}
function observeLibSentinel(){const s=$('#libSentinel');if(!s)return;if(libObs){libObs.disconnect();libObs=null}if(!('IntersectionObserver'in window))return;libObs=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){if(libObs){libObs.disconnect();libObs=null}libAppendMore()}},{rootMargin:'700px'});libObs.observe(s)}
function skelHTML(title){return `<div class="sectionHead"><div><h1>${esc(title)}</h1></div></div><div class="skelWrap" aria-hidden="true"><div class="skel"></div><div class="skel"></div><div class="skel"></div><div class="skel"></div><div class="skel"></div><div class="skel"></div></div><p class="muted">טוען…</p>`}
function invKey(t){return String(t||'').split(/[,(]/)[0].replace(/[\d.\/½¼¾]+/g,' ').replace(/\s+/g,' ').trim()}
function whatCanCook(items){const names=items.map(i=>invKey(i.name)).filter(Boolean);if(!names.length)return '<section class="cookable"><h2>מה אפשר להכין?</h2><p>הוסיפו פריטים למלאי ונתאים לכם מתכונים.</p></section>';const rows=recipes.map(r=>{const keys=r.ingredients.map(invKey).filter(Boolean),have=keys.filter(k=>names.some(n=>n&&(k.includes(n)||n.includes(k))));return {r,have:have.length,total:keys.length}}).filter(x=>x.total&&x.have).sort((a,b)=>(b.have/b.total)-(a.have/a.total)||b.have-a.have).slice(0,6);return `<section class="cookable"><h2>מה אפשר להכין?</h2>${rows.length?rows.map(x=>`<button type="button" class="cookableRow" data-open-recipe="${esc(x.r.id)}"><b>${esc(x.r.name)}</b><span>יש לך ${x.have} מתוך ${x.total} מרכיבים</span></button>`).join(''):'<p>עוד אין התאמה בין המלאי למתכונים.</p>'}</section>`}
async function layoutInventory(){let items=[];try{items=(await API.call('/inventory')).items}catch{return '<section class="empty"><h2>המלאי לא נטען</h2><p>בדקו חיבור ונסו שוב.</p><button data-view="inventory">ניסיון נוסף</button></section>'}const zones={pantry:'מזווה',fridge:'מקרר',freezer:'מקפיא'};return `<div class="sectionHead"><div><button data-view="home">← חזרה לבית</button><h1>מה יש בבית</h1></div></div><p>מלאי לפי מקום אחסון. הפריטים נשמרים בחשבון.</p>${whatCanCook(items)}<form id="inventoryForm" class="inventoryForm"><label>שם הפריט<input name="name" required maxlength="150" placeholder="לדוגמה: בצל"></label><label>כמות<input name="quantity" type="number" min="0.01" max="100000" step="any" value="1" required></label><label>יחידה<input name="unit" maxlength="30" placeholder="יחידות / ק״ג"></label><label>מקום<select name="zone"><option value="pantry">מזווה</option><option value="fridge">מקרר</option><option value="freezer">מקפיא</option></select></label><label>תוקף (רשות)<input name="expires_at" type="date"></label><label>הערה<input name="note" maxlength="500"></label><button class="primary">הוספת פריט</button></form>${Object.entries(zones).map(([zone,label])=>`<section class="backupPanel"><h2>${label}</h2>${items.filter(x=>x.zone===zone).length?items.filter(x=>x.zone===zone).map(x=>`<div class="inventoryRow"><div><b>${esc(x.name)}</b> · ${x.quantity} ${esc(x.unit)} ${x.expires_at?`  · ${x.expires_at < new Date().toISOString().slice(0,10)?'תוקף עבר: ':'תוקף עד: '}${esc(x.expires_at)}`:''}${x.note?`<small>${esc(x.note)}</small>`:''}</div><button data-inventory-edit="${x.id}">עריכה</button><button data-inventory-delete="${x.id}" aria-label="מחיקת ${esc(x.name)}">מחיקה</button></div>`).join(''):'<p class="muted">אין פריטים כאן.</p>'}</section>`).join('')}`}
const shopKey=t=>String(t||'').replace(/\s+/g,' ').trim().toLowerCase();
function modPrefs(){try{return JSON.parse(localStorage.getItem('tavlin-settings')||'{}')}catch(e){return{}}}
function modEnabled(name){const p=modPrefs();if(name==='shopping')return p.shoppingLists!==false;if(name==='inventory')return p.inventory!==false;return true}
function applyModuleVisibility(){const s=modEnabled('shopping'),i=modEnabled('inventory');document.querySelectorAll('[data-menu-view="shopping"]').forEach(b=>b.style.display=s?'':'none');document.querySelectorAll('[data-menu-view="inventory"]').forEach(b=>b.style.display=i?'':'none')}
function shopGroups(items){const by=new Map();for(const x of items){const rec=x.recipe_id?recipes.find(r=>r.id===x.recipe_id):null,g=rec?'ל'+rec.name:'כללי';if(!by.has(g))by.set(g,[]);by.get(g).push(x)}return [...by.entries()].map(([g,list])=>`<h3 class="shopGroup">${esc(g)}</h3>`+list.map(x=>`<div class="shoppingItem ${x.checked?'done':''}"><label><input type="checkbox" data-shop-check="${x.id}" ${x.checked?'checked':''}> <span>${esc(x.text)}</span></label><button data-shop-delete="${x.id}" aria-label="מחיקה">✕</button></div>`).join('')).join('')}
window.shopClearChecked=async function(){const items=(await API.call('/shopping')).items.filter(x=>x.checked);for(const x of items)await API.call('/shopping/'+x.id,{method:'DELETE'});toast(items.length?'הפריטים המסומנים נוקו':'אין פריטים מסומנים');render('shopping')};
window.shopUncheckAll=async function(){const items=(await API.call('/shopping')).items.filter(x=>x.checked);for(const x of items)await API.call('/shopping/'+x.id,{method:'PUT',body:JSON.stringify({text:x.text,checked:false})});render('shopping')};
window.shopDedupe=async function(){const items=(await API.call('/shopping')).items,seen=new Set();let n=0;for(const x of items){const k=shopKey(x.text);if(seen.has(k)){await API.call('/shopping/'+x.id,{method:'DELETE'});n++}else seen.add(k)}toast(n?`אוחדו ${n} כפילויות`:'לא נמצאו כפילויות');render('shopping')};
function smartSummaryHTML(items){
 if(!window.ShoppingSmart||!items.length)return '';
 try{
  const agg=ShoppingSmart.aggregate(items.map(x=>x.text));
  if(!agg.items.length)return '';
  return `<section class="backupPanel smartBuy"><h2>🧮 סיכום קניות חכם</h2><p class="muted">יחידות קנייה (ק״ג / ליטר / אריזות) במקום כוסות וכפות — כפילויות אוחדו:</p><ul class="smartBuyList">${agg.items.map(it=>`<li><b>${esc(it.name)}</b> — ${esc(it.display)}${it.packageNote?` <span class="muted">(${esc(it.packageNote)})</span>`:''}</li>`).join('')}</ul></section>`;
 }catch(e){return ''}
}
async function layoutShopping(){const prefsNow=JSON.parse(localStorage.getItem('tavlin-settings')||'{}');if(prefsNow.shoppingLists===false)return `<div class="sectionHead"><button data-view="home">← חזרה לבית</button></div><section class="empty"><h2>רשימות קניות כבויות</h2><p>אפשר להפעיל אותן במסך ההגדרות.</p><button data-action="settings">פתיחת הגדרות</button></section>`;let items=[];try{items=(await API.call('/shopping')).items}catch(e){return `<div class="sectionHead"><button data-view="home">← חזרה לבית</button></div><section class="empty"><h2>רשימת הקניות לא נטענה</h2><p>בדקו את החיבור ונסו שוב.</p><button data-view="shopping">ניסיון נוסף</button></section>`}return `<div class="sectionHead"><div><button data-view="home">← חזרה לבית</button><h1>רשימת קניות</h1></div></div><form id="shoppingForm" class="search"><input name="text" placeholder="מה צריך לקנות?" required><button class="primary">הוספה</button></form>${smartSummaryHTML(items)}${items.length?`<div class="shopBar"><button type="button" id="shopClearChecked">🧹 נקה מסומנים (${items.filter(x=>x.checked).length})</button><button type="button" id="shopUncheckAll">☐ בטל סימון הכל</button><button type="button" id="shopDedupe">🔗 איחוד כפילויות</button></div>`:''}<section class="shoppingList">${items.length?shopGroups(items):'<div class="empty"><h2>הרשימה ריקה</h2><p>הוסיפו פריטים ידנית או מתוך מתכון.</p></div>'}</section>`}
async function toggleFavorite(id){const next=!favoriteIds.has(id);try{await API.call('/favorites/'+id,{method:next?'PUT':'DELETE'});if(next)favoriteIds.add(id);else favoriteIds.delete(id);render('library');toast(next?'נוסף למועדפים':'הוסר מהמועדפים')}catch{toast('לא ניתן לשנות מועדפים כרגע. נסו שוב.')}}
function combineShoppingLines(lines){const groups=new Map(),out=[];for(const raw of lines){const text=raw.trim(),m=text.match(/^(\d+(?:[.,]\d+)?)\s+(בצל|בצלים|עגבניה|עגבניות|תפוחי אדמה)\s*$/);if(!m){if(text&&!out.includes(text))out.push(text);continue}const canonical={'בצלים':'בצל','עגבניות':'עגבניה'}[m[2]]||m[2],n=Number(m[1].replace(',','.'));if(!Number.isFinite(n)||n<=0||n>1000){if(!out.includes(text))out.push(text);continue}if(!groups.has(canonical))groups.set(canonical,{n:0,shown:m[2],original:[]});const g=groups.get(canonical);g.n+=n;g.original.push(text)}for(const g of groups.values()){if(g.original.length===1)out.push(g.original[0]);else out.push(`${Math.round(g.n*100)/100} ${g.shown}`)}return out}
async function addSelectedShopping(){const ids=[...shoppingSelection].filter(id=>id!=='__mode'),selected=recipes.filter(r=>ids.includes(r.id));if(!selected.length)return;const originals=selected.flatMap(r=>r.ingredients.map(x=>x.trim()).filter(Boolean)),ingredients=combineShoppingLines(originals);const d=document.createElement('dialog');d.className='shoppingPreview';d.innerHTML=`<div class="importPreviewPanel"><div class="dlgHead"><h2>בדיקת רשימת הקניות</h2><button type="button" data-close-shop>← חזרה</button></div><p>${selected.length} מתכונים · ${originals.length} שורות מקור · ${ingredients.length} פריטים להוספה</p><p class="notice">רק בצל, עגבנייה ותפוחי אדמה נסכמים כשנכתבו ככמות מספרית של פריטים. כמויות אחרות נשארות כשורות נפרדות; בדקו את הרשימה לפני הוספה.</p><ul>${ingredients.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button type="button" class="primary" data-confirm-shop>הוספת ${ingredients.length} פריטים</button><p data-shop-status role="status"></p></div>`;document.body.append(d);d.showModal();d.querySelector('[data-close-shop]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.querySelector('[data-confirm-shop]').onclick=async()=>{const b=d.querySelector('[data-confirm-shop]');b.disabled=true;let done=0;for(const text of ingredients){try{await API.call('/shopping',{method:'POST',body:JSON.stringify({text})});done++}catch{d.querySelector('[data-shop-status]').textContent=`${done} מתוך ${ingredients.length} פריטים נוספו. בדקו את הרשימה לפני ניסיון נוסף.`;return}}shoppingSelection.clear();d.close();render('shopping');toast(`${done} פריטים נוספו`)}}
async function addRecipeShopping(id){const r=recipes.find(x=>x.id===id);let have=new Set();try{have=new Set((await API.call('/shopping')).items.map(x=>shopKey(x.text)))}catch{}let added=0;for(const text of r.ingredients){const k=shopKey(text);if(have.has(k))continue;have.add(k);await API.call('/shopping',{method:'POST',body:JSON.stringify({text,recipe_id:id})});added++}toast(added?`נוספו ${added} מצרכים (כפילויות דולגו)`:'כל המצרכים כבר ברשימה')}
function layoutBackup(){return `<div class="sectionHead"><button data-view="home">← חזרה לבית</button><h1>גיבוי ושיתוף</h1></div><p>המתכונים נשמרים בחשבון תבלין ומסתנכרנים בין המכשירים. במכשיר נשמר מטמון לעבודה לא מקוונת.</p><section class="backupPanel"><h2>גיבוי מתכונים</h2><p>מוריד קובץ JSON של המתכונים מתוך חשבון תבלין, כולל מצרכים, שלבים והערות. תמונות, סריקות, גרסאות, היסטוריה והגדרות אינן כלולות כרגע.</p><button class="primary" data-action="export">הורדת גיבוי</button><label class="backupUpload">בחירת קובץ גיבוי לתצוגה מקדימה<input id="importFile" type="file" accept="application/json,.json"></label></section><section class="backupPanel"><h2>פרטיות ועבודה לא מקוונת</h2><p>החשבון ונתוני המתכונים נשמרים במסד הנתונים של תבלין. מטמון מקומי מאפשר לפתוח מתכונים שכבר נטענו גם ללא רשת.</p><div class="notice">מחיקת נתוני הדפדפן מסירה את המטמון המקומי, אך מתכונים שסונכרנו נשארים בחשבון. עדיין מומלץ להוריד גיבוי תקופתי.</div></section><section class="backupPanel"><h2><img src="assets/mascot.webp?v=83" alt="" class="chatMascot"> עוזר חכם 🤖</h2><div id="aiChat" class="chatLog"><div class="bubble ai">היי! אני העוזר החכם של תבלין 🍳<br>אני עוזר <b>רק</b> בענייני מתכונים ואוכל — שאלו אותי על מתכונים, מרכיבים, תחליפים או טכניקות בישול.</div></div><div class="row"><input id="aiInput" placeholder="שאלו כל שאלה על בישול..." autocomplete="off"><button class="primary" id="aiSend">שליחה</button></div><p class="muted" id="aiStatus">מופעל על ידי AI · דורש חיבור לאינטרנט</p></section>${modEnabled('inventory')?`<section class="backupPanel"><h2>המלאי שלי 🧺</h2><p class="muted">סמנו מה יש בבית — ההמלצות והמתכונים ידעו מה חסר.</p><div id="invPreview" class="chips"></div><div><button class="primary" id="invEdit">עריכת מלאי</button></div></section>`:''}`}
