/* ---- FAB peek ---- */
const FAB_STATE_KEY='tavlin-fab-state';
function setFabPeek(peek){const f=$('#aiFab');if(!f)return;f.classList.toggle('peek',peek);if(peek)f.classList.remove('chat-open');try{localStorage.setItem(FAB_STATE_KEY,peek?'peek':'open')}catch(e){}}
function setFabChatOpen(open){const f=$('#aiFab');if(f)f.classList.toggle('chat-open',!!open&&!f.classList.contains('peek'))}
$('#aiFab').onclick=()=>{const p=$('#aiPopup');if($('#aiFab').classList.contains('peek')){setFabPeek(false);p.hidden=false;setFabChatOpen(true);$('#aiPopupField')?.focus();refreshChatVoiceUI();return}const open=p.hidden;p.hidden=!open;setFabChatOpen(open);if(open){$('#aiPopupField')?.focus();refreshChatVoiceUI()}};
$('#aiPopupClose').onclick=()=>{$('#aiPopup').hidden=true;setFabChatOpen(false);setFabPeek(true)};
function aiPopupBubble(text,me){const log=$('#aiPopupLog');if(!log)return null;const d=document.createElement('div');d.className='bubble '+(me?'me':'ai');d.innerHTML=text;log.appendChild(d);log.scrollTop=log.scrollHeight;return d}
let aiPopupBusy=false;
async function sendAiPopup(){
 const inp=$('#aiPopupField');if(!inp||aiPopupBusy)return;const text=inp.value.trim();if(!text)return;
 aiPopupBusy=true;inp.value='';setMascotThinking(true);aiPopupBubble(esc(text),true);
 const typing=aiPopupBubble('מקליד... 🤔',false);if(typing)typing.classList.add('typing');
 const hist=[...$('#aiPopupLog').querySelectorAll('.bubble:not(.typing)')].map(b=>({role:b.classList.contains('me')?'user':'assistant',text:b.textContent}));
 const recipeBook=(typeof recipes!=='undefined'?recipes:[]).map(r=>({name:r.name,category:r.category,ingredients:r.ingredients}));
 let firstTokenAt=0,acc='',answer=null;
 try{
  await streamChat(hist,t=>{if(!firstTokenAt){firstTokenAt=performance.now();if(typing)typing.remove();answer=aiPopupBubble('',false)}
   acc+=t;if(answer){answer.textContent=acc;const log=$('#aiPopupLog');if(log)log.scrollTop=log.scrollHeight}},recipeBook);
  if(!firstTokenAt)throw new Error('empty_stream');
 }catch(e){
  if(typing)typing.remove();if(answer)answer.remove();
  const res=await apiAI('chat',{messages:hist,recipes:recipeBook});
  const txt=res.ok?res.reply:'⚠️ '+res.message;
  aiPopupBubble(esc(txt),false);acc=txt;
 }
 setMascotThinking(false);aiPopupBusy=false;
 speakChatAnswer(acc);
}
/* ---- chat voice: mic dictation + TTS answers, Shabbat-guarded ---- */
const CHAT_TTS_KEY='tavlin-chat-tts';
function chatTtsOn(){try{return localStorage.getItem(CHAT_TTS_KEY)!=='off'}catch(e){return true}}
function setChatTts(on){try{localStorage.setItem(CHAT_TTS_KEY,on?'on':'off')}catch(e){}const b=$('#aiPopupTts');if(b){b.textContent=on?'🔊':'🔇';b.classList.toggle('off',!on)}}
async function chatVoiceAllowed(){try{const p=JSON.parse(localStorage.getItem('tavlin-settings')||'{}');if(p.voice===false)return false;if(window.Voice&&await Voice.isShabbatNow())return false;return true}catch(e){return true}}
function chatMicSupported(){return !!(window.SpeechRecognition||window.webkitSpeechRecognition)}
async function refreshChatVoiceUI(){const ok=await chatVoiceAllowed();const mic=$('#aiPopupMic'),tts=$('#aiPopupTts');if(mic)mic.style.display=(ok&&chatMicSupported())?'':'none';if(tts)tts.style.display=ok?'':'none';setChatTts(chatTtsOn())}
let chatRec=null;
async function chatDictate(){
 if(!(await chatVoiceAllowed())){toast('הקול מושבת כעת (שבת/חג או הגדרות)');return}
 const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('הדפדפן לא תומך בהקלטה');return}
 const mic=$('#aiPopupMic'),field=$('#aiPopupField');if(!field)return;
 if(chatRec){try{chatRec.stop()}catch(e){}return}
 if(window.Voice)try{Voice.stop()}catch(e){}
 chatRec=new SR();chatRec.lang='he-IL';chatRec.interimResults=true;chatRec.continuous=false;
 if(mic)mic.classList.add('listening');
 chatRec.onresult=e=>{let fin='',inter='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)fin+=t;else inter+=t}field.value=(fin||inter).trim();if(fin){try{chatRec.stop()}catch(e){}}};
 chatRec.onend=async()=>{if(mic)mic.classList.remove('listening');chatRec=null;if(window.Voice){try{if(Voice.autoStart)await Voice.autoStart()}catch(e){}}if(field.value.trim()&&!$('#aiPopup').hidden)sendAiPopup()};
 chatRec.onerror=()=>{if(mic)mic.classList.remove('listening');chatRec=null;if(window.Voice){try{if(Voice.autoStart)Voice.autoStart()}catch(e){}}};
 try{chatRec.start()}catch(e){if(mic)mic.classList.remove('listening');chatRec=null;toast('לא ניתן להתחיל הקלטה')}
}
function ttsClean(t){return String(t||'').replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu,'').replace(/[*_#]/g,'').trim().slice(0,600)}
async function speakChatAnswer(text){
 const clean=ttsClean(text);if(!clean||clean.indexOf('⚠')===0)return;
 if(!chatTtsOn())return;if(!(await chatVoiceAllowed()))return;
 if(!('speechSynthesis'in window))return;
 const fab=$('#aiFab');try{
  const u=new SpeechSynthesisUtterance(clean);u.lang='he-IL';u.rate=1;
  u.onend=u.onerror=()=>{if(fab)fab.classList.remove('speaking')};
  if(fab)fab.classList.add('speaking');
  speechSynthesis.cancel();speechSynthesis.speak(u);
 }catch(e){if(fab)fab.classList.remove('speaking')}
}
$('#aiPopupMic').onclick=chatDictate;
$('#aiPopupTts').onclick=()=>{const on=!chatTtsOn();setChatTts(on);if(!on&&'speechSynthesis'in window){try{speechSynthesis.cancel();$('#aiFab')?.classList.remove('speaking')}catch(e){}}toast(on?'הקראת תשובות פעילה':'הקראת תשובות כבויה')};
async function openChatVoice(){setFabPeek(false);const p=$('#aiPopup');if(p.hidden)p.hidden=false;setFabChatOpen(true);$('#aiPopupField')?.focus();await refreshChatVoiceUI();if(await chatVoiceAllowed()&&chatMicSupported())chatDictate()}
$('#aiPopupSend').onclick=sendAiPopup;
