/* ---- Mascot thinking state (v83) ---- */
let thinkBlinkTimer=null;
function setMascotThinking(on){
 window.mascotThinking=!!on;
 const fab=$('#aiFab'),fabImg=fab?fab.querySelector('img'):null,pop=$('#aiPopup'),popImg=pop?pop.querySelector('.aiPopupMascot'):null;
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(on){
  if(fabImg)fabImg.src='assets/mascot-thinking-spoon.webp?v=83';
  if(popImg)popImg.src='assets/mascot-thinking-spoon.webp?v=83';
  if(!reduce){if(fab)fab.classList.add('thinking');if(pop)pop.classList.add('thinking');clearTimeout(thinkBlinkTimer);thinkBlinkTimer=setTimeout(thinkBlinkLoop,2000)}
 }else{
  clearTimeout(thinkBlinkTimer);
  if(fabImg)fabImg.src='assets/mascot.webp?v=83';
  if(popImg)popImg.src='assets/mascot.webp?v=83';
  if(fab)fab.classList.remove('thinking');if(pop)pop.classList.remove('thinking');
 }
}
function thinkBlinkLoop(){
 if(!window.mascotThinking)return;
 const fabImg=document.querySelector('#aiFab img'),popImg=document.querySelector('#aiPopup .aiPopupMascot'),bl='assets/mascot-thinking-spoon-blink.webp?v=83',sp='assets/mascot-thinking-spoon.webp?v=83';
 if(fabImg)fabImg.src=bl;if(popImg)popImg.src=bl;
 setTimeout(()=>{if(!window.mascotThinking)return;if(fabImg)fabImg.src=sp;if(popImg)popImg.src=sp;thinkBlinkTimer=setTimeout(thinkBlinkLoop,2000)},400);
}
(function(){const fab=$('#aiFab');if(!fab)return;const img=fab.querySelector('img');if(!img)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;let blinking=false;function blink(){if(blinking||document.hidden||window.mascotThinking){schedule();return}blinking=true;img.src='assets/mascot-blink.webp?v=83';setTimeout(()=>{img.src='assets/mascot.webp?v=83';blinking=false;schedule()},400)}function schedule(){setTimeout(blink,2000)}schedule()})();
