function renderNav(){const nav=document.querySelector('header nav');if(!nav)return;const sel=getNavShortcuts();let html='<button data-view="home">בית</button><button data-view="library">המתכונים שלי</button>';for(const id of sel){if((id==='shopping'&&!modEnabled('shopping'))||(id==='inventory'&&!modEnabled('inventory')))continue;const s=NAV_SHORTCUTS.find(x=>x.id===id);if(!s)continue;html+=s.type==='view'?`<button data-view="${s.view}">${s.label}</button>`:`<button data-action="${s.action}">${s.label}</button>`}nav.innerHTML=html;bind()}
function renderNavShortcutsBox(){const box=$('#navShortcutsBox');if(!box)return;const sel=getNavShortcuts();box.innerHTML=NAV_SHORTCUTS.filter(s=>!((s.id==='shopping'&&!modEnabled('shopping'))||(s.id==='inventory'&&!modEnabled('inventory')))).map(s=>`<label class="setRow"><input type="checkbox" data-nav-shortcut="${s.id}" ${sel.includes(s.id)?'checked':''}> ${s.label}</label>`).join('')}
const prefs=JSON.parse(localStorage.getItem('tavlin-settings')||'{}');document.body.dataset.theme=prefs.theme||'cream';document.body.classList.toggle('largeText',!!prefs.largeText);renderNav();$('#settingsBtn').onclick=()=>{const f=$('#settingsForm');Object.entries(prefs).forEach(([k,v])=>{if(f[k])f[k].type==='checkbox'?f[k].checked=!!v:f[k].value=v});$('#settingsDialog').showModal();loadAccountBox();loadAiSettingsBox();renderNavShortcutsBox();if(window.TimerSounds){const bx=$('#timerSndBox');if(bx){bx.innerHTML=TimerSounds.settingsHTML();TimerSounds.bindPreview(bx)};if(window.Voice){const vx=$('#voiceSettingsBox');if(vx){vx.innerHTML=Voice.settingsHTML();Voice.refreshShabbatState()}}}};$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=e.target,o={};[...f.elements].filter(x=>x.name).forEach(x=>o[x.name]=x.type==='checkbox'?x.checked:x.value);o.navShortcuts=[...document.querySelectorAll('[data-nav-shortcut]:checked')].map(x=>x.dataset.navShortcut);localStorage.setItem('tavlin-settings',JSON.stringify(o));Object.assign(prefs,o);document.body.dataset.theme=o.theme;document.body.classList.toggle('largeText',o.largeText);renderNav();applyModuleVisibility();$('#settingsDialog').close();toast('ההגדרות נשמרו')};
const API={async call(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});if(r.status===401){showLogin();throw new Error('unauthorized')}if(!r.ok)throw new Error(await r.text());return r.json()},async load(){const x=await this.call('/recipes');recipes=x.recipes;try{favoriteIds=new Set((await this.call('/favorites')).recipe_ids)}catch{favoriteIds=new Set();toast('לא ניתן לטעון מועדפים כרגע')}for(const r of recipes){r.ingredients=Array.isArray(r.ingredients)?r.ingredients:JSON.parse(r.ingredients);r.steps=Array.isArray(r.steps)?r.steps:JSON.parse(r.steps)}return recipes}};
function showLogin(){if($('#loginOverlay'))return;const d=document.createElement('div');d.id='loginOverlay';d.className='splitOverlay';d.innerHTML='<form id="loginForm" style="margin:auto;background:var(--paper);padding:30px;border-radius:22px;width:min(360px,90vw)"><h1>כניסה לתבלין</h1><label>שם משתמש<input name="username" value="יוני" readonly></label><label>סיסמה<input name="password" type="password" required></label><button class="primary">כניסה</button><p id="loginStatus"></p></form>';document.body.append(d);$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=e.target,r=await fetch('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:f.username.value,password:f.password.value})});if(r.ok){d.remove();await API.load();render()}else $('#loginStatus').textContent='הפרטים אינם נכונים'}}
refresh=async function(){try{const remote=await API.load();for(const r of remote)await DB.req(DB.store('recipes','readwrite').put(r));return remote}catch(e){recipes=(await DB.all()).filter(x=>!x.deletedAt).sort((a,b)=>b.updatedAt-a.updatedAt);if(navigator.onLine&&e.message==='unauthorized')showLogin();else document.querySelector('#loginOverlay')?.remove();return recipes}};
const localPut=DB.put.bind(DB);DB.put=async function(v){const exists=recipes.some(r=>r.id===v.id);const x=await API.call(exists?'/recipes/'+v.id:'/recipes',{method:exists?'PUT':'POST',body:JSON.stringify(v)});await localPut(v);return x};
const oldDel=DB.del.bind(DB);DB.del=async function(id){await API.call('/recipes/'+id,{method:'DELETE'});return oldDel(id)};

// Conservative, recipe-specific gate: a language-model score by itself cannot
// prove that a page contains a recipe. Uncertain pages go to manual entry.
function handwritingQuality(result){
 const q=result?.quality||{},text=String(result?.text||''),flat=text.replace(/\s+/g,' ');
 const section=/(?:מצרכים|מרכיבים|חומרים|אופן\s*הכנה|הוראות\s*הכנה|הכנה)/.test(flat);
 const quantity=/(?:\d|[¼½¾]|חצי|רבע|שליש|שתי|שני|אחד|אחת|כוס|כפית|כף|גרם|קילו|מיליליטר|מ״ל)/.test(flat);
 const cooking=/(?:לבשל|לאפות|לטגן|לחמם|לערבב|להוסיף|לחתוך|לשפוך|להניח|מערבבים|מוסיפים|אופים|מבשלים|טורפים|קוצצים|תנור|מחבת|קערה)/.test(flat);
 return !q.invalid&&q.lineCount>=3&&q.characters>=35&&q.hebrewRatio>=.65&&q.peak>=.70&&q.margin>=2.5&&section&&quantity&&cooking;
}
// The handwriting path is user-selected. Its output is an editable draft only.
async function transcribeHandwritten(file){
 const form=$('#scanForm'),status=$('#ocrStatus'),review=$('#ocrReview'),submit=form.querySelector('button.primary');
 form.raw.value='';form.dataset.hasImage='';review.hidden=true;submit.disabled=true;status.hidden=false;
 try{
   const src=await fileData(file);$('#scanPreview').src=src;$('#scanPreview').hidden=false;
   if(!window.TavlinHTR){await new Promise((ok,no)=>{const s=document.createElement('script');s.src='/htr/recognizer.js';s.onload=ok;s.onerror=()=>no(Error('recognizer_load'));document.head.append(s)})}
   const result=await TavlinHTR.recognize(file,text=>status.textContent=text);
   form.dataset.hasImage='1';review.hidden=false;
   if(!handwritingQuality(result)){status.textContent='כתב היד לא זוהה בביטחון מספק.';review.innerHTML='<h3 class="ocrMissing">לא זיהיתי</h3><p class="ocrMissing">אי אפשר לסמוך על התמלול האוטומטי של העמוד הזה. הקלידו את המתכון ידנית; שום דבר לא נשמר.</p>';return}
   form.raw.value=result.text;status.textContent=`זוהו ${result.lines} שורות - זוהי טיוטה לא בדוקה.`;
   review.innerHTML='<h3>זיהיתי - צריך לבדוק</h3><p class="ocrMissing">תקנו את השורות, הכמויות והשלבים לפני מעבר למסך הבדיקה. זיהוי כתב היד ניסיוני. שום דבר לא נשמר אוטומטית.</p>';
 }catch(err){form.dataset.hasImage='1';status.textContent='זיהוי כתב היד לא הצליח.';review.hidden=false;review.innerHTML='<h3 class="ocrMissing">לא זיהיתי</h3><p class="ocrMissing">אפשר להקליד ידנית; שום דבר לא נשמר.</p>';console.error('HTR failed',err)}finally{submit.disabled=false}
}
